        events: ['Stop'],
        hookCommand: '$PILOT_DATA/hooks/sample-agent-hook.sh',
        format: 'nested',
        matcher: '*',
      },
    }));
    await fs.writeFile(path.join(dataDir, 'deployed-agents.json'), JSON.stringify({
      'daemon-agent': {
        deployMode: 'hook',
        deployedAt: '2020-01-01T00:00:00.000Z',
        installedBy: 'daemon',
      },
    }));
  });

  afterEach(async () => {
    restoreHome();
    await fs.rm(tmp, { recursive: true, force: true });
