      dataDir,
      pilotDir,
      builtinAgentsDir: path.join(pilotDir, 'agents.d'),
      writeResult: true,
      agentsFlag: 'sample-agent',
      identity: { identity: 'f'.repeat(64), source: 'cgroup' },
    });
    expect(result.exitCode).toBe(0);
    const state = JSON.parse(await fs.readFile(path.join(dataDir, 'deployed-agents.json'), 'utf8'));
    expect(state['daemon-agent']).toEqual({
      deployMode: 'hook',
      deployedAt: '2020-01-01T00:00:00.000Z',
      installedBy: 'daemon',
    });
    expect(state['sample-agent'].installedBy).toBe('hook-install');
  });
});

import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');

describe('public installer SLS config output', () => {
  it('shell installer accepts SLS API Key without printing it in overwrite diff', async () => {
    const content = await readFile(path.join(rootDir, 'deploy/installer-opensource.sh'), 'utf8');

    expect(content).toContain('SLS_API_KEY=""');
    expect(content).toContain('--sls-api-key)');
    expect(content).toContain('--sls-api-key=*)');
    expect(content).toContain('cannot be used with --sls-ak-id or --sls-ak-secret');
    expect(content).toContain('LP_SLS_API_KEY="[REDACTED]"');
    expect(content).toContain("label: 'sls.mode'");
    expect(content).not.toContain("label: 'sls.apiKey'");
  });

  it('PowerShell installer accepts SLS API Key without printing it in overwrite diff', async () => {
    const content = await readFile(path.join(rootDir, 'deploy/installer-opensource.ps1'), 'utf8');

    expect(content).toContain('[string]$SlsApiKey');
    expect(content).toContain('cannot be used with -SlsAkId or -SlsAkSecret');
    expect(content).toContain('slsApiKey');
    expect(content).toContain("label: 'sls.mode'");
    expect(content).not.toContain("label: 'sls.apiKey'");
  });

  it.each(['deploy/installer-opensource.sh', 'deploy/installer-opensource.ps1'])('%s writes API Key mode and clears AK/SK fields', async (installer) => {
    const content = await readFile(path.join(rootDir, installer), 'utf8');

    expect(content).toContain("config.sls.mode = 'apiKey'");
    expect(content).toContain('config.sls.apiKey');
    expect(content).toContain('delete config.sls.accessKeyId');
    expect(content).toContain('delete config.sls.accessKeySecret');
    expect(content).toContain("config.sls.mode = 'ak'");
    expect(content).toContain('delete config.sls.apiKey');
  });

  it('deploy/installer-opensource.sh supports --all-agents to collect every agent', async () => {
    const content = await readFile(path.join(rootDir, 'deploy/installer-opensource.sh'), 'utf8');

    expect(content).toContain('ALL_AGENTS=0');
    expect(content).toContain('--all-agents)');
    expect(content).toContain('if [ "$ALL_AGENTS" = "1" ]; then');
    expect(content).toContain("const allAgentsMode = '${ALL_AGENTS}';");
    expect(content).toContain("if (allAgentsMode === '1') {");
    expect(content).toContain('delete agent.enabled;');
    expect(content).not.toContain('delete config.agents;');
  });

  it('deploy/installer-opensource.ps1 supports -AllAgents to collect every agent', async () => {
    const content = await readFile(path.join(rootDir, 'deploy/installer-opensource.ps1'), 'utf8');

    expect(content).toContain('[switch]$AllAgents');
    expect(content).toContain('if ($AllAgents) {');
    expect(content).toContain('allAgentsMode     = $(if ($AllAgents) { "1" } else { "" })');
    expect(content).toContain("if (opts.allAgentsMode === '1') {");
    expect(content).toContain('delete agent.enabled;');
    expect(content).not.toContain('delete config.agents;');
  });
});

import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');

describe('installer mask replacement mode', () => {
  it('the shell installer validates and writes preview mode', async () => {
    const content = await readFile(
      path.join(rootDir, 'deploy/installer-opensource.sh'),
      'utf8',
    );

    expect(content).toContain('MASK_REPLACEMENT_MODE=""');
    expect(content).toContain('--mask-replacement-mode)');
    expect(content).toContain("use 'placeholder' or 'preview'");
    expect(content).toContain('mask.replacementMode');
    expect(content).toContain('config.mask.replacementMode = maskReplacementMode');
  });

  it('the PowerShell installer validates and writes preview mode', async () => {
    const content = await readFile(
      path.join(rootDir, 'deploy/installer-opensource.ps1'),
      'utf8',
    );

    expect(content).toContain('[string]$MaskReplacementMode');
    expect(content).toContain('@("placeholder", "preview")');
    expect(content).toContain('mask.replacementMode');
    expect(content).toContain('config.mask.replacementMode = opts.maskReplacementMode');
  });
});

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import * as os from 'node:os';
import { execFileSync } from 'node:child_process';
import { resolveOpenClawHost } from '../../../src/deployment/openclaw-version-resolver.js';
import { PluginInjectStrategy } from '../../../src/deployment/plugin-inject-strategy.js';
import type { AgentDefinition } from '../../../src/types/index.js';

// Execute only the actual config writer, never the installer/service commands.
// PowerShell's embedded JS is executed on every platform; native PS startup is
// a separate Windows acceptance gate, not claimed by these tests.
describe.each(['shell', 'powershell'])('%s OpenClaw installation state', platform => {
  let root: string;
  let dataDir: string;
  let configPath: string;
  let writerOutput: string;
  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'pilot-oc-install-'));
    dataDir = path.join(root, 'custom pilot data');
    await fs.mkdir(dataDir);
    configPath = path.join(dataDir, 'config.json');
  });
  afterEach(async () => { await fs.rm(root, { recursive: true, force: true }); });

  async function writeConfig(probe: unknown[], selected = 'openclaw,codex', explicit = false, all = false) {
    const file = platform === 'shell' ? 'deploy/installer-opensource.sh' : 'deploy/installer-opensource.ps1';
    const installer = await fs.readFile(file, 'utf8');
    const cleanEnv = { PATH: process.env.PATH, HOME: root, USERPROFILE: root, SystemRoot: process.env.SystemRoot, TEMP: root };
    if (platform === 'shell') {
      const start = installer.indexOf('write_config() {');
      const end = installer.indexOf('\n# ============================================================', start);
      const fn = installer.slice(start, end);
      writerOutput = execFileSync('bash', ['-c', `set -eo pipefail\nmsg() { :; }\n${fn}\nwrite_config`], {
        env: { ...cleanEnv, DATA_DIR: dataDir, NODE_BIN: process.execPath,
          PROBE_RESULT: JSON.stringify(probe), SELECTED_AGENTS: selected, AGENT_SELECTION_EXPLICIT: explicit ? '1' : '0', ALL_AGENTS: all ? '1' : '0' },
        timeout: 10000,
      }).toString();
    } else {
      const start = installer.indexOf("const fs = require('fs');\nlet raw = fs.readFileSync(process.argv[1]");
      const end = installer.indexOf("\n'@ $cfgTmp", start);
      expect(start).toBeGreaterThan(0);
      expect(end).toBeGreaterThan(start);
      const opts = path.join(root, 'opts.json');
      await fs.writeFile(opts, JSON.stringify({ configPath, dataDir, selectedAgents: selected,
        probeResult: JSON.stringify(probe), agentSelectionExplicit: explicit ? '1' : '0',
        allAgentsMode: all ? '1' : '' }));
      writerOutput = execFileSync(process.execPath, ['-e', installer.slice(start, end), opts], { env: cleanEnv, timeout: 10000 }).toString();
    }
    return JSON.parse(await fs.readFile(configPath, 'utf8'));
  }
  const probe = (detected: boolean, entry?: string) => [
    { id: 'openclaw', detected, ...(entry ? { openclawCliPath: entry } : {}) },
    { id: 'codex', detected: true },
  ];

  it.each(['2026.3.8', '2026.6.10'])('auto discovery -> install -> fresh service env -> idempotent injection (%s)', async version => {
    const app = path.join(root, 'app');
    await fs.mkdir(app);
    const entry = path.join(app, 'openclaw.mjs');
    await fs.writeFile(entry, '/* never executed */');
    await fs.writeFile(path.join(app, 'package.json'), JSON.stringify({ name: 'openclaw', version }));
    const discovered = await resolveOpenClawHost({}, app);
    expect(discovered?.binding).toBe('auto-entry');
    const installed = await writeConfig(probe(true, discovered!.executable));
    expect(installed.agents.openclaw).toEqual({ enabled: true, cliPath: entry });
    const env = { AGENT_DATA_COLLECTION_CONFIG: configPath, PATH: '' };
    const resolved = await resolveOpenClawHost(env, dataDir);
    expect(resolved).toMatchObject({ version, executable: entry, binding: 'persisted-entry' });
    const gatewayConfig = path.join(root, 'gateway.json');
    const def: AgentDefinition = { id: 'openclaw', displayName: 'OpenClaw', deployMode: 'plugin-inject',
      detection: { paths: [], commands: [] }, pluginInject: { configPaths: [gatewayConfig],
        configShape: 'openclaw-nested', createIfMissing: true, pluginId: 'loongsuite-pilot-openclaw',
        pluginSpec: 'file://$PILOT_DATA/plugins/openclaw' } };
    const strategy = new PluginInjectStrategy(dataDir, root, () => resolveOpenClawHost(env, dataDir));
    expect((await strategy.deploy(def)).success).toBe(true);
    const before = await fs.readFile(gatewayConfig, 'utf8');
    const mtime = (await fs.stat(gatewayConfig)).mtimeMs;
    expect(JSON.parse(before).plugins.entries['loongsuite-pilot-openclaw'].hooks?.allowConversationAccess)
      .toBe(version === '2026.3.8' ? undefined : true);
    await writeConfig(probe(true, discovered!.executable));
    expect(await strategy.needsDeploy(def)).toBe(false);
    expect((await strategy.deploy(def)).success).toBe(true);
    expect(await fs.readFile(gatewayConfig, 'utf8')).toBe(before);
    expect((await fs.stat(gatewayConfig)).mtimeMs).toBe(mtime);
  });

  it.each([true, false, undefined])('preserves previous enabled=%s and entry after an automatic discovery miss', async enabled => {
    const previous = { ...(enabled !== undefined ? { enabled } : {}), cliPath: '/missing/openclaw.mjs', captureMessageContent: false };
    await fs.writeFile(configPath, JSON.stringify({ agents: { openclaw: previous } }));
    const config = await writeConfig(probe(false), 'codex');
    expect(config.agents.openclaw).toEqual(previous);
    expect(config.agents.codex.enabled).toBe(true);
  });
  it('still honors an explicit disable selection', async () => {
    await fs.writeFile(configPath, JSON.stringify({ agents: { openclaw: { enabled: true } } }));
    expect((await writeConfig(probe(false), 'codex', true)).agents.openclaw.enabled).toBe(false);
  });
  it.each([false, true])('persists an installer recovery and survives a fresh service (explicit=%s)', async explicit => {
    const old = path.join(root, 'old/openclaw.mjs');
    const app = path.join(root, 'app'); await fs.mkdir(app);
    const entry = path.join(app, 'openclaw.mjs');
    await fs.writeFile(entry, '/* never executed */');
    await fs.writeFile(path.join(app, 'package.json'), JSON.stringify({ name: 'openclaw', version: '2026.3.8' }));
    await fs.writeFile(configPath, JSON.stringify({ agents: { openclaw: { enabled: true, cliPath: old, captureMessageContent: false } } }));
    const env = { HOME: root, AGENT_DATA_COLLECTION_CONFIG: configPath, PATH: '' };
    expect(await resolveOpenClawHost(env, app)).toBeNull();
    const candidate = await resolveOpenClawHost(env, app, { mode: 'installer' });
    expect(candidate?.recoveredFrom).toBe(old);
    const updated = await writeConfig(probe(true, candidate!.executable), 'openclaw,codex', explicit);
    expect(updated.agents.openclaw).toEqual({ enabled: true, cliPath: entry, captureMessageContent: false });
    expect(writerOutput).toContain(`OpenClaw: updating launch entry ${JSON.stringify(old)} -> ${JSON.stringify(entry)}`);
    expect(await resolveOpenClawHost(env, root)).toMatchObject({ executable: entry, binding: 'persisted-entry' });
  });
  it('enables recovery only in the public installer probe invocation', async () => {
    const script = await fs.readFile(platform === 'shell' ? 'deploy/installer-opensource.sh' : 'deploy/installer-opensource.ps1', 'utf8');
    expect(script).toContain('--installer --config-path');
  });
  it.each([false, true])('installs the fixed child behind broken parent metadata (recover=%s)', async recover => {
    const app = path.join(root, 'app');
    const child = path.join(app, 'openclaw');
    await fs.mkdir(child, { recursive: true });
    const entry = path.join(child, 'openclaw.mjs');
    await fs.writeFile(entry, '/* never executed */');
    await fs.writeFile(path.join(child, 'package.json'), JSON.stringify({ name: 'openclaw', version: '2026.3.8' }));
    await fs.writeFile(path.join(app, 'package.json'), '{');
    const old = path.join(root, 'removed/openclaw.mjs');
    if (recover) await fs.writeFile(configPath, JSON.stringify({ agents: { openclaw: { enabled: true, cliPath: old, captureMessageContent: false } } }));
    const before = recover ? await fs.readFile(configPath, 'utf8') : undefined;
    const env = { HOME: root, AGENT_DATA_COLLECTION_CONFIG: configPath, PATH: '' };
    if (recover) expect(await resolveOpenClawHost(env, app)).toBeNull();
    const candidate = await resolveOpenClawHost(env, app, { mode: 'installer' });
    expect(candidate).toMatchObject({ executable: entry, binding: 'auto-entry' });
    if (recover) {
      expect(candidate?.recoveredFrom).toBe(old);
      expect(await fs.readFile(configPath, 'utf8')).toBe(before);
    } else await expect(fs.stat(configPath)).rejects.toMatchObject({ code: 'ENOENT' });
    const updated = await writeConfig(probe(true, candidate!.executable));
    expect(updated.agents.openclaw).toMatchObject({ enabled: true, cliPath: entry });
    if (recover) expect(updated.agents.openclaw.captureMessageContent).toBe(false);
    expect(await resolveOpenClawHost(env, root)).toMatchObject({ executable: entry, binding: 'persisted-entry', conversationAccess: false });
  });
  it('does not enable a missing OpenClaw on first installation', async () => {
    expect((await writeConfig(probe(false), 'codex')).agents.openclaw.enabled).toBe(false);
  });
  it('round-trips entry paths with spaces, Unicode and shell metacharacters as data', async () => {
    const entry = '/opt/test 空格/quote\'"$`/openclaw.mjs';
    expect((await writeConfig(probe(true, entry))).agents.openclaw.cliPath).toBe(entry);
  });
  it.each([false, true])('discovers even with explicit/all-agent selection (all=%s)', async all => {
    const entry = '/app/openclaw.mjs';
    const config = await writeConfig(probe(true, entry), all ? '' : 'openclaw', true, all);
    expect(config.agents.openclaw.cliPath).toBe(entry);
    expect(config.agents.openclaw.enabled).toBe(all ? undefined : true);
    if (!all) expect(config.agents.codex.enabled).toBe(false);
  });
  it('all-agent mode removes enable gates but not existing metadata on probe failure', async () => {
    await fs.writeFile(configPath, JSON.stringify({ agents: {
      openclaw: { enabled: false, cliPath: '/keep/openclaw.mjs' },
      codex: { enabled: false, captureMessageContent: false }, future: { enabled: false, custom: 'keep' },
    } }));
    expect((await writeConfig([], '', false, true)).agents).toEqual({
      openclaw: { cliPath: '/keep/openclaw.mjs' }, codex: { captureMessageContent: false }, future: { custom: 'keep' },
    });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'node:fs/promises';
import * as os from 'node:os';
import * as path from 'node:path';
import { isolateAgentHome } from '../../helpers/isolated-agent-home.js';
import {
  HOOK_INSTALL_REASONS,
  classifyDeployError,
  definitionAtInstallHome,
  hintForReason,
  hookInstallResultPath,
  markHookInstallAlarmSent,
  mergeInstalledAgents,
  runHookInstall,
  selectAgents,
  toPublicReport,
} from '../../../src/deployment/hook-install-service.js';
import { resolveDeploymentScope } from '../../../src/deployment/deployment-scope.js';

vi.mock('node:os', async importOriginal => {
  const actual = await importOriginal<typeof import('node:os')>();
  const homedir = vi.fn(actual.homedir);
  return { ...actual, homedir, default: { ...actual, homedir } };
});

vi.mock('../../../src/utils/logger.js', () => ({
  createLogger: () => ({ info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() }),
  redirectRootLoggerToStderr: vi.fn(),
}));

describe('hook install service', () => {
  let tmp: string;
  let dataDir: string;
  let pilotDir: string;
  let home: string;
  let restoreHome: () => void;

  beforeEach(async () => {
    tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'pilot-hook-install-'));
    restoreHome = isolateAgentHome(tmp);
    dataDir = path.join(tmp, 'data');
    pilotDir = path.join(tmp, 'pilot');
    home = path.join(tmp, 'agent-home');
    await fs.mkdir(path.join(pilotDir, 'agents.d'), { recursive: true });
    await fs.mkdir(home, { recursive: true });
    await fs.writeFile(path.join(pilotDir, 'agents.d', 'sample-agent.json'), JSON.stringify({
      id: 'sample-agent',
      displayName: 'Sample',
      deployMode: 'hook',
      detection: { paths: [home], commands: [] },
      hook: {
        settingsPath: path.join(home, 'settings.json'),
        events: ['Stop'],
        hookCommand: '$PILOT_DATA/hooks/sample-agent-hook.sh',
        format: 'nested',
        matcher: '*',
      },
    }));
  });

  afterEach(async () => {
    restoreHome();
    await fs.rm(tmp, { recursive: true, force: true });
  });

  function run(overrides: Partial<Parameters<typeof runHookInstall>[0]> = {}) {
    return runHookInstall({
      dataDir,
      pilotDir,
      builtinAgentsDir: path.join(pilotDir, 'agents.d'),
      writeResult: true,
      identity: { identity: 'c'.repeat(64), source: 'cgroup' },
      ...overrides,
    });
  }

  it('treats unset, empty, and literal null as full detection, and only none as skip', async () => {
    expect(selectAgents(undefined, undefined)).toEqual({ kind: 'detect', warnLiteralNull: false });
    expect(selectAgents(undefined, '')).toEqual({ kind: 'detect', warnLiteralNull: false });
    expect(selectAgents(undefined, 'null')).toEqual({ kind: 'detect', warnLiteralNull: true });
    expect(selectAgents('null', 'claude-code')).toEqual({ kind: 'detect', warnLiteralNull: true });
    expect(selectAgents(undefined, 'none')).toEqual({ kind: 'skip' });
    expect(selectAgents('none', undefined)).toEqual({ kind: 'skip' });
    expect(selectAgents('sample-agent', 'none').kind).toBe('named');

    const skipped = await run({ agentsFlag: 'none' });
    expect(skipped.exitCode).toBe(0);
    expect(skipped.wroteResult).toBe(false);
    await expect(fs.access(hookInstallResultPath(dataDir))).rejects.toThrow();

    const detected = await run({ envAgents: 'null' });
    expect(detected.warnings).toEqual([
      'LOONGSUITE_PILOT_AGENTS or --agents is the literal "null"; detecting all agents.',
    ]);
    expect(detected.report.scope).toBe('detected');
    expect(detected.report.agents.map(agent => agent.id)).toEqual(['sample-agent']);
    expect(detected.exitCode).toBe(0);
  });

  it('fails unknown ids and agents that were named but not detected, and every reason has a hint', async () => {
    for (const reason of HOOK_INSTALL_REASONS) {
      expect(hintForReason(reason, 'sample-agent').length).toBeGreaterThan(0);
    }

    const unknown = await run({ agentsFlag: 'missing-agent' });
    expect(unknown.exitCode).toBe(1);
    expect(unknown.report.agents[0]).toMatchObject({
      id: 'missing-agent',
      status: 'failed',
      reason: 'unknown-id',
    });
    expect(unknown.report.agents[0].hint).toBeTruthy();
    expect(unknown.report.scope).toBe('detected');
    expect(resolveDeploymentScope(
      { identity: 'c'.repeat(64), source: 'cgroup' },
      unknown.report,
    )).toBe('auto');

    await fs.rm(home, { recursive: true, force: true });
    const missing = await run({ agentsFlag: 'sample-agent' });
    expect(missing.exitCode).toBe(1);
    expect(missing.report.agents[0]).toMatchObject({
      status: 'failed',
      reason: 'not-detected',
    });
    expect(missing.report.agents[0].hint).toContain('home');
  });

  it('reports uid-mismatch from an injected euid without requiring the CI user to be root', async () => {
    const result = await run({
      agentsFlag: 'sample-agent',
      homes: { 'sample-agent': home },
      euid: 0,
      homeOwner: async () => 1000,
    });
    expect(result.exitCode).toBe(1);
    expect(result.report.agents[0]).toMatchObject({ reason: 'uid-mismatch', status: 'failed' });
    expect(result.report.agents[0].hint).toContain('agent user');
    await expect(fs.access(path.join(home, 'settings.json'))).rejects.toThrow();
  });

  it('writes a result file with the same agents and scope as the public JSON', async () => {
    const result = await run({ agentsFlag: 'sample-agent' });
    expect(result.report.scope).toBe('named');
    const disk = JSON.parse(await fs.readFile(hookInstallResultPath(dataDir), 'utf8'));
    const pub = toPublicReport(result.report);
    expect(pub.scope).toBe(disk.scope);
    expect(pub.agents).toEqual(disk.agents);
    expect(disk.alarmSent).toBe(true);
    expect(pub).not.toHaveProperty('alarmSent');
    expect(result.report.agents[0].status).toBe('ok');
  });

  it('does not treat a path containing json or an empty settings file as invalid JSON', async () => {
    expect(classifyDeployError('cannot write /tmp/settings.json: EACCES')).toBe('deploy-failed');
    expect(classifyDeployError(Object.assign(new Error('denied'), { code: 'EACCES' }))).toBe('deploy-failed');
    expect(classifyDeployError(new SyntaxError('Unexpected token'))).toBe('invalid-settings');

    await fs.writeFile(path.join(pilotDir, 'agents.d', 'sample-agent.json'), JSON.stringify({
      id: 'sample-agent',
      displayName: 'Sample',
      deployMode: 'hook',
      detection: { paths: [home], commands: [] },
      hook: {
        settingsPath: path.join(home, 'settings.json'),
        settingsSyntax: 'jsonc',
        events: ['Stop'],
        hookCommand: '$PILOT_DATA/hooks/sample-agent-hook.sh',
        format: 'nested',
        matcher: '*',
      },
    }));
    await fs.writeFile(path.join(home, 'settings.json'), '{ /* keep */ }\n');
    const commented = await run({ agentsFlag: 'sample-agent' });
    expect(commented.report.agents[0].reason).toBeNull();
    await fs.writeFile(path.join(home, 'settings.json'), '   \n');
    const empty = await run({ agentsFlag: 'sample-agent' });
    expect(empty.report.agents[0].reason).toBeNull();
    expect(empty.report.agents[0].status).toBe('ok');
  });

  it('keeps a Kiro hook under agents/ and writes CLI settings in the same home', async () => {
    const kiroHome = path.join(tmp, 'custom-kiro');
    const defaultHome = path.join(tmp, 'default-kiro');
    await fs.writeFile(path.join(pilotDir, 'agents.d', 'kiro-cli.json'), JSON.stringify({
      id: 'kiro-cli',
      displayName: 'Kiro CLI',
      deployMode: 'hook',
      detection: { paths: [defaultHome], commands: [] },
      hook: {
        settingsPath: path.join(defaultHome, 'agents', 'pilot-kiro.json'),
        events: ['stop'],
        hookCommand: '$PILOT_DATA/hooks/kiro-cli-loongsuite-pilot-hook.sh',
        format: 'flat',
        matcher: '*',
        eventSubcommand: 'as-is',
        kiroAgent: { name: 'pilot-kiro', tools: ['read'] },
      },
    }));
    const placed = definitionAtInstallHome({
      id: 'kiro-cli',
      displayName: 'Kiro CLI',
      deployMode: 'hook',
      detection: { paths: [defaultHome], commands: [] },
      hook: {
        settingsPath: path.join(defaultHome, 'agents', 'pilot-kiro.json'),
        events: ['stop'],
        hookCommand: 'hook.sh',
        format: 'flat',
      },
    }, kiroHome);
    expect(placed?.hook?.settingsPath).toBe(path.join(kiroHome, 'agents', 'pilot-kiro.json'));

    const result = await run({
      agentsFlag: 'kiro-cli',
      homes: { 'kiro-cli': kiroHome },
    });
    expect(result.exitCode).toBe(0);
    expect(await fs.readFile(path.join(kiroHome, 'agents', 'pilot-kiro.json'), 'utf8')).toContain('stop');
    expect(await fs.readFile(path.join(kiroHome, 'settings', 'cli.json'), 'utf8')).toContain('pilot-kiro');
    await expect(fs.access(path.join(defaultHome, 'agents', 'pilot-kiro.json'))).rejects.toThrow();
  });

  it('writes a plugin config under --home instead of the default directory', async () => {
    const custom = path.join(tmp, 'custom-opencode');
    const defaults = path.join(tmp, 'default-opencode');
    await fs.writeFile(path.join(pilotDir, 'agents.d', 'opencode.json'), JSON.stringify({
      id: 'opencode',
      displayName: 'OpenCode',
      deployMode: 'plugin-inject',
      detection: { paths: [defaults], commands: [] },
      pluginInject: {
        createIfMissing: true,
        configPaths: [path.join(defaults, 'opencode.jsonc')],
        pluginSpec: 'file:///tmp/pilot-plugin.mjs',
        pluginId: 'loongsuite-pilot-opencode',
      },
    }));
    const result = await run({
      agentsFlag: 'opencode',
      homes: { opencode: custom },
    });
    expect(result.exitCode).toBe(0);
    await fs.access(path.join(custom, 'opencode.jsonc'));
    await expect(fs.access(path.join(defaults, 'opencode.jsonc'))).rejects.toThrow();
  });

  it('reports a missing hook as not installed until a record exists', async () => {
    const status = await run({ agentsFlag: 'sample-agent', mode: 'status', writeResult: false });
    expect(status.report.agents[0].reason).toBe('not-detected');
  });

  it('keeps an earlier named agent when a later install names a different one', async () => {
    const otherHome = path.join(tmp, 'other-home');
    await fs.mkdir(otherHome, { recursive: true });
    await fs.writeFile(path.join(pilotDir, 'agents.d', 'other-agent.json'), JSON.stringify({
      id: 'other-agent',
      displayName: 'Other',
      deployMode: 'hook',
      detection: { paths: [otherHome], commands: [] },
      hook: {
        settingsPath: path.join(otherHome, 'settings.json'),
        events: ['Stop'],
        hookCommand: '$PILOT_DATA/hooks/other-agent-hook.sh',
        format: 'nested',
        matcher: '*',
      },
    }));
    const first = await run({ agentsFlag: 'sample-agent' });
    expect(first.exitCode).toBe(0);
    const sampleSettings = path.join(home, 'settings.json');
    const sampleText = await fs.readFile(sampleSettings, 'utf8');

    const second = await run({ agentsFlag: 'other-agent' });
    expect(second.exitCode).toBe(0);
    expect(await fs.readFile(sampleSettings, 'utf8')).toBe(sampleText);
    const disk = JSON.parse(await fs.readFile(hookInstallResultPath(dataDir), 'utf8'));
    const ids = disk.agents.filter((agent: { status: string }) => agent.status === 'ok').map((agent: { id: string }) => agent.id);
    expect(ids).toEqual(expect.arrayContaining(['sample-agent', 'other-agent']));
  });

  it('keeps named scope through a full detect so the next named install still merges', async () => {
    const otherHome = path.join(tmp, 'later-home');
    await fs.mkdir(otherHome, { recursive: true });
    const first = await run({ agentsFlag: 'sample-agent' });
    expect(first.report.scope).toBe('named');

    const detected = await run({});
    expect(detected.exitCode).toBe(0);
    const afterDetect = JSON.parse(await fs.readFile(hookInstallResultPath(dataDir), 'utf8'));
    expect(afterDetect.scope).toBe('named');
    expect(afterDetect.agents.some((agent: { id: string; status: string }) =>
      agent.id === 'sample-agent' && (agent.status === 'ok' || agent.status === 'up-to-date'))).toBe(true);

    await fs.writeFile(path.join(pilotDir, 'agents.d', 'other-agent.json'), JSON.stringify({
      id: 'other-agent',
      displayName: 'Other',
      deployMode: 'hook',
      detection: { paths: [otherHome], commands: [] },
      hook: {
        settingsPath: path.join(otherHome, 'settings.json'),
        events: ['Stop'],
        hookCommand: '$PILOT_DATA/hooks/other-agent-hook.sh',
        format: 'nested',
        matcher: '*',
      },
    }));
    const second = await run({ agentsFlag: 'other-agent' });
    expect(second.exitCode).toBe(0);
    const disk = JSON.parse(await fs.readFile(hookInstallResultPath(dataDir), 'utf8'));
    expect(disk.scope).toBe('named');
    const ids = disk.agents
      .filter((agent: { status: string }) => agent.status === 'ok' || agent.status === 'up-to-date')
      .map((agent: { id: string }) => agent.id);
    expect(ids).toEqual(expect.arrayContaining(['sample-agent', 'other-agent']));
  });

  it('mergeInstalledAgents keeps a previous success when the same id fails later', () => {
    const merged = mergeInstalledAgents(
      [{ id: 'grok-build', status: 'ok', reason: null, hint: null, settingsPath: '/a', deployMode: 'hook' }],
      [{ id: 'grok-build', status: 'failed', reason: 'uid-mismatch', hint: 'x', settingsPath: '/b', deployMode: 'hook' }],
    );
    expect(merged.map(agent => agent.status)).toEqual(['ok', 'failed']);
  });

  it('does not let an alarm mark replace a hook install report written under the same lock', async () => {
    const file = hookInstallResultPath(dataDir);
    await fs.mkdir(dataDir, { recursive: true });
    await fs.writeFile(file, JSON.stringify({
      schema: 1,
      identity: 'c'.repeat(64),
      ts: 'old',
      scope: 'detected',
      agents: [],
      alarmSent: false,
    }));
    const installed = run({ agentsFlag: 'sample-agent' });
    const marked = markHookInstallAlarmSent(file, 'old');
    await Promise.all([installed, marked]);
    const disk = JSON.parse(await fs.readFile(file, 'utf8'));
    expect(disk.ts).not.toBe('old');
    expect(disk.agents.some((agent: { id: string }) => agent.id === 'sample-agent')).toBe(true);
  });

  it('does not mark a newer hook-install report as already alarmed', async () => {
    const file = hookInstallResultPath(dataDir);
    await fs.mkdir(dataDir, { recursive: true });
    await fs.writeFile(file, JSON.stringify({
      schema: 1,
      identity: 'c'.repeat(64),
      ts: 'new',
      scope: 'named',
      agents: [],
      alarmSent: false,
    }));
    expect(await markHookInstallAlarmSent(file, 'old')).toBe('stale');
    const disk = JSON.parse(await fs.readFile(file, 'utf8'));
    expect(disk.ts).toBe('new');
    expect(disk.alarmSent).toBe(false);
  });
});

import { afterEach, expect, it, vi } from 'vitest';
import * as fs from 'node:fs/promises';
import * as os from 'node:os';
import * as path from 'node:path';
import { isolateAgentHome } from '../../helpers/isolated-agent-home.js';
import { AgentDefLoader } from '../../../src/deployment/agent-def-loader.js';
import { resolveHome } from '../../../src/utils/fs-utils.js';

vi.mock('node:os', async importOriginal => {
  const actual = await importOriginal<typeof import('node:os')>();
  const homedir = vi.fn(actual.homedir);
  return { ...actual, homedir, default: { ...actual, homedir } };
});

let root: string;
afterEach(async () => {
  vi.unstubAllEnvs();
  if (root) await fs.rm(root, { recursive: true, force: true });
});

it('isolates built-in config targets and restores inherited directory overrides', async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'agent-home-'));
  for (const key of ['HOME', 'USERPROFILE', 'GROK_HOME', 'HERMES_HOME', 'PI_CODING_AGENT_DIR', 'DSH_HOME', 'OPENCLAW_CONFIG_PATH', 'OPENCLAW_STATE_DIR']) {
    vi.stubEnv(key, path.join(root, 'outside', key));
  }
  vi.stubEnv('XDG_CONFIG_HOME', undefined);
  const keys = [
    'HOME', 'USERPROFILE', 'APPDATA', 'LOCALAPPDATA', 'XDG_CONFIG_HOME',
    'CLAUDE_CONFIG_DIR', 'CODEX_HOME', 'GROK_HOME', 'HERMES_HOME',
    'PI_CODING_AGENT_DIR', 'DSH_HOME',
    'OPENCLAW_CONFIG_PATH', 'OPENCLAW_STATE_DIR',
  ];
  const directoryEnv = () => Object.fromEntries(keys.map(key => [key, process.env[key]]));
  const beforeEnv = directoryEnv();
  const beforeHome = os.homedir();
  const home = path.join(root, 'sandbox');
  const restore = isolateAgentHome(home);
  try {
    expect(os.homedir()).toBe(home);
    expect(resolveHome('~')).toBe(home);
    expect(process.env.DSH_HOME).toBe(path.join(home, '.dsh'));
    expect(process.env.OPENCLAW_CONFIG_PATH).toBe('');
    expect(process.env.OPENCLAW_STATE_DIR).toBe('');
    const definitions = await new AgentDefLoader({
      pilotDir: process.cwd(),
      dataDir: home,
      builtinDir: path.join(process.cwd(), 'agents.d'),
      localDir: path.join(home, 'agents.d.local'),
    }).load();
    expect(definitions.length).toBeGreaterThan(0);
    for (const def of definitions) {
      const targets = [
        def.hook?.settingsPath, def.hook?.trustToml?.configPath,
        ...(def.pluginInject?.configPaths ?? []), def.directoryPlugin?.targetDir,
      ].filter((target): target is string => Boolean(target));
      for (const target of targets) {
        expect(path.relative(home, target), def.id).not.toMatch(/^\.\.(?:[\\/]|$)/);
        expect(path.isAbsolute(target), def.id).toBe(true);
      }
    }
  } finally { restore(); }
  expect(directoryEnv()).toEqual(beforeEnv);
  expect(os.homedir()).toBe(beforeHome);
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import * as os from 'node:os';
import { AgentDefLoader } from '../../../src/deployment/agent-def-loader.js';

vi.mock('../../../src/utils/logger.js', () => ({
  createLogger: () => ({
    info: vi.fn(),
    debug: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
  }),
}));

describe('AgentDefLoader', () => {
  let tmpDir: string;
  let builtinDir: string;
  let localDir: string;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'agent-def-loader-'));
    builtinDir = path.join(tmpDir, 'agents.d');
    localDir = path.join(tmpDir, 'agents.d.local');
    await fs.mkdir(builtinDir, { recursive: true });
    await fs.mkdir(localDir, { recursive: true });
  });

  afterEach(async () => {
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  function makeLoader() {
    return new AgentDefLoader({
      builtinDir,
      localDir,
      pilotDir: '/opt/pilot',
      dataDir: '/home/user/.loongsuite-pilot',
    });
  }

  it('loads valid definitions from builtin directory', async () => {
    const def = {
      id: 'test-agent',
      displayName: 'Test',
      deployMode: 'hook',
      detection: { paths: ['~/.test'], commands: [] },
      hook: { settingsPath: '~/.test/settings.json', events: ['Stop'], hookCommand: 'test.sh', format: 'flat' },
    };
    await fs.writeFile(path.join(builtinDir, 'test.json'), JSON.stringify(def));

    const loader = makeLoader();
    const defs = await loader.load();

    expect(defs).toHaveLength(1);
    expect(defs[0].id).toBe('test-agent');
  });

  it('skips invalid JSON files', async () => {
    await fs.writeFile(path.join(builtinDir, 'broken.json'), '{invalid');

    const loader = makeLoader();
    const defs = await loader.load();

    expect(defs).toHaveLength(0);
  });

  it('skips definitions missing required fields', async () => {
    const def = { id: 'missing-fields' };
    await fs.writeFile(path.join(builtinDir, 'bad.json'), JSON.stringify(def));

    const loader = makeLoader();
    const defs = await loader.load();

    expect(defs).toHaveLength(0);
  });

  it('local definitions override builtin by id', async () => {
