import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import * as fs from 'node:fs/promises';
import * as os from 'node:os';
import * as path from 'node:path';
import { cleanupDshIntegration } from '../../../assets/plugins/dsh/cleanup.mjs';

const MARKER = 'PILOT-OBSERVABILITY-MANAGED';

function block(createdFile) {
  return [
    `# BEGIN ${MARKER} (created-file: ${createdFile})`,
    '# entryId=loongsuite-pilot-observability',
    '# pluginSource=file:///pilot/plugins/dsh/plugin.mjs',
    '# pluginHash=abc123',
    '- insert:',
    "  - id: 'loongsuite-pilot-observability'",
    '    name: file:///pilot/plugins/dsh/plugin.mjs',
    `# END ${MARKER}`,
    '',
  ].join('\n');
}

describe('DSH uninstall cleanup helper', () => {
  let tmpDir;
  let patchPath;
  let pluginDir;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'dsh-cleanup-'));
    patchPath = path.join(tmpDir, 'dsh-home', 'cordis.patch.yml');
    pluginDir = path.join(tmpDir, 'pilot-data', 'plugins', 'dsh');
    await fs.mkdir(path.dirname(patchPath), { recursive: true });
    await fs.mkdir(pluginDir, { recursive: true });
    await fs.writeFile(path.join(pluginDir, '.collection-enabled'), 'enabled\n');
  });

  afterEach(async () => {
    await fs.rm(tmpDir, { recursive: true, force: true });
  });

  it('removes only the Pilot block and preserves third-party bytes verbatim', async () => {
    const before = '# user-before\n- id: user-a\n  name: file:///a\n';
    const after = '# user-after\r\n- id: user-b\r\n  name: file:///b\r\n';
    await fs.writeFile(patchPath, before + block(false) + after);

    const result = await cleanupDshIntegration({ patchPath, pluginDir, marker: MARKER });
    expect(result).toMatchObject({ success: true, changed: true });
    expect(await fs.readFile(patchPath, 'utf-8')).toBe(before + after);
    await expect(fs.stat(path.join(pluginDir, '.collection-enabled')))
      .rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('deletes an otherwise empty patch file created by Pilot', async () => {
    await fs.writeFile(patchPath, block(true));
    const result = await cleanupDshIntegration({ patchPath, pluginDir, marker: MARKER });
    expect(result.success).toBe(true);
    await expect(fs.stat(patchPath)).rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('does not create a DSH home when the patch file is already absent', async () => {
    const missingHome = path.join(tmpDir, 'missing-dsh-home');
    const missingPatch = path.join(missingHome, 'cordis.patch.yml');

    const result = await cleanupDshIntegration({
      patchPath: missingPatch,
      pluginDir,
      marker: MARKER,
    });

    expect(result).toEqual({ success: true, changed: false });
    await expect(fs.stat(missingHome)).rejects.toMatchObject({ code: 'ENOENT' });
    await expect(fs.stat(path.join(pluginDir, '.collection-enabled')))
      .rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('fails closed and preserves an incomplete marker block', async () => {
    const invalid = `# BEGIN ${MARKER}\n- insert: []\n`;
    await fs.writeFile(patchPath, invalid);
    const result = await cleanupDshIntegration({ patchPath, pluginDir, marker: MARKER });
    expect(result.success).toBe(false);
    expect(await fs.readFile(patchPath, 'utf-8')).toBe(invalid);
  });

  it.each([
    ['unmatched END', `user-before\n# END ${MARKER}\nuser-after\n`],
    ['nested BEGIN', `# BEGIN ${MARKER}\n# BEGIN ${MARKER}\n${block(false)}`],
    ['duplicate blocks', `${block(false)}${block(false)}`],
  ])('fails closed and preserves malformed marker bytes: %s', async (_label, invalid) => {
    await fs.writeFile(patchPath, invalid);
    const result = await cleanupDshIntegration({ patchPath, pluginDir, marker: MARKER });
    expect(result.success).toBe(false);
    expect(await fs.readFile(patchPath, 'utf-8')).toBe(invalid);
  });

  it('serializes concurrent stale-lock cleanup without corrupting user bytes', async () => {
    const before = '# user-before\n';
    const after = '# user-after\n';
    await fs.writeFile(patchPath, before + block(false) + after);
    const lockPath = `${patchPath}.loongsuite-pilot.lock`;
    await fs.writeFile(lockPath, 'abandoned');
    const old = new Date(Date.now() - 60_000);
    await fs.utimes(lockPath, old, old);

    const [a, b] = await Promise.all([
      cleanupDshIntegration({ patchPath, pluginDir, marker: MARKER }),
      cleanupDshIntegration({ patchPath, pluginDir, marker: MARKER }),
    ]);
    expect(a.success).toBe(true);
    expect(b.success).toBe(true);
    expect(await fs.readFile(patchPath, 'utf-8')).toBe(before + after);
    await expect(fs.stat(lockPath)).rejects.toMatchObject({ code: 'ENOENT' });
    await expect(fs.stat(`${lockPath}.reclaim`)).rejects.toMatchObject({ code: 'ENOENT' });
  });

  it('wires cleanup before installation asset removal on Unix and Windows', async () => {
    const unix = await fs.readFile(path.resolve('deploy/installer-opensource.sh'), 'utf-8');
    const unixUninstall = unix.slice(unix.indexOf('cmd_uninstall()'));
    expect(unixUninstall.indexOf('remove_dsh_yaml_patch'))
      .toBeLessThan(unixUninstall.indexOf('rm -rf "${_cache_dir:?}/versions"'));

    const windows = await fs.readFile(path.resolve('deploy/installer-opensource.ps1'), 'utf-8');
    const windowsUninstall = windows.slice(windows.indexOf('function Cmd-Uninstall'));
    expect(windowsUninstall.indexOf('Remove-DshYamlPatch'))
      .toBeLessThan(windowsUninstall.indexOf('Remove-PilotInstallationFiles'));
    expect(unix).toContain('dshPatchPath');
    expect(windows).toContain('dshPatchPath');
  });
});

// Stop-PilotService only ends the current task instance. The updater task's 5-minute
// repeating trigger (and RestartCount) relaunches it while Deploy-Package is still
// filling in a versions/ directory that neither `current` nor `previous` names, and
// gcOldVersions deletes that directory. Disable-ScheduledTask is a write to the task
// definition, so it actually holds the watchdog for the rest of the deploy.
//
// Disable must run BEFORE Stop: Disable does not kill a running instance, but
// Stop-Process -Force while the task is still Enabled can arm RestartCount
// (collector interval is 1 minute). Unix `loongsuite-pilot stop` already unloads
// launchd / disables systemd first.
//
// Only the .ps1 installers are pinned here: the relaunch is a Task Scheduler artefact,
// and the .sh installers unload launchd / disable systemd in `loongsuite-pilot stop`.
// installer-opensource.ps1 is ratcheted on the GitHub PR, not on the internal one.
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';

const INTERNAL_PS1 = [
  'deploy/installer.ps1',
  'deploy/installer-inner.ps1',
];
const OPENSOURCE_PS1 = 'deploy/installer-opensource.ps1';
const PS1_INSTALLERS = [...INTERNAL_PS1, OPENSOURCE_PS1];

const TAG = 'pilot-hold-tasks-during-deploy';

const read = (f) => readFileSync(f, 'utf-8');

const blockOf = (text, tag) => {
  const re = new RegExp(`^\\s*# >>> ${tag} >>>\\n[\\s\\S]*?^\\s*# <<< ${tag} <<<\\n`, 'm');
  const m = text.match(re);
  return m ? m[0] : null;
};

const codeOf = (text) => text
  .split('\n')
  .filter(line => !/^\s*#/.test(line))
  .join('\n');

const functionBody = (text, name) => {
  const start = text.indexOf(`function ${name} {`);
  expect(start, `${name} not found`).toBeGreaterThan(-1);
  const rest = text.slice(start);
  const end = rest.search(/\nfunction \S+ \{/);
  return rest.slice(0, end === -1 ? rest.length : end);
};

const present = PS1_INSTALLERS.filter(existsSync);
const patched = present.filter(f => blockOf(read(f), TAG));
// Identity and Disable-before-Stop are pinned on the installers this tree
// owns. The internal repo updates installer{,-inner}.ps1 here and sends
// installer-opensource.ps1 to GitHub as its own PR; the GitHub tree has
// only the opensource file. Mixing them in one identity set fails until
// opensource sync lands the GitHub copy.
const withBlock = (files) => files.filter(existsSync).filter(f => blockOf(read(f), TAG));
const PINNED = withBlock(INTERNAL_PS1).length > 0
  ? withBlock(INTERNAL_PS1)
  : withBlock([OPENSOURCE_PS1]);

describe('installers disable scheduled tasks for the duration of a deploy', () => {
  it('defines the hold/restore helpers', () => {
    expect(patched.length).toBeGreaterThanOrEqual(1);
    for (const file of INTERNAL_PS1.filter(existsSync)) {
      expect(blockOf(read(file), TAG), `${file}: ${TAG} block missing`).toBeTruthy();
    }
    for (const file of patched) {
      const code = codeOf(blockOf(read(file), TAG));
      expect(code, file).toMatch(/function Disable-PilotScheduledTasksDuringDeploy/);
      expect(code, file).toMatch(/function Enable-PilotScheduledTasksAfterDeploy/);
      expect(code, file).toMatch(/Disable-ScheduledTask/);
      expect(code, file).toMatch(/Enable-ScheduledTask/);
    }
  });

  it('the block is byte-identical across the pinned .ps1 installers', () => {
    expect(PINNED.length).toBeGreaterThanOrEqual(1);
    const blocks = PINNED.map(f => blockOf(read(f), TAG));
    expect(blocks.filter(b => !b)).toEqual([]);
    expect(new Set(blocks).size).toBe(1);
  });

  it('disables both the collector and the updater task', () => {
    const code = codeOf(blockOf(read(patched[0]), TAG));
    expect(code).toMatch(/LoongsuitePilot-\$tag/);
    expect(code).toMatch(/LoongsuitePilotUpdater-\$tag/);
  });

  it('the shared block tells callers to Disable before Stop', () => {
    const block = blockOf(read(PINNED[0]), TAG);
    expect(block).toMatch(/Disable BEFORE Stop-PilotService/);
  });

  it('does not abort the install when Disable is denied', () => {
    // Elevated first installs leave the tasks owned by Administrators; the same
    // Access is denied that blocks schtasks /Delete would also block Disable.
    // Swallowing that is required -- a denied hold must not turn a working reinstall
    // into a failed one.
    const code = codeOf(blockOf(read(patched[0]), TAG));
    expect(code).toMatch(/Disable-ScheduledTask[\s\S]*catch/);
    expect(code).not.toMatch(/Disable-ScheduledTask[\s\S]*exit 1/);
  });

  it('re-enables only the tasks this deploy actually disabled', () => {
    // Enabling a task we never held would turn on something the user had disabled,
    // or a task whose Disable failed (and is therefore still enabled).
    const code = codeOf(blockOf(read(patched[0]), TAG));
    expect(code).toMatch(/PILOT_HELD_TASK_NAMES/);
    expect(code).toMatch(/PILOT_HELD_TASK_NAMES \+= \$taskName/);
  });

  it('keeps failed Enable names on the list for finally to retry', () => {
    // Unconditional wipe after the loop makes a failed success-path Enable a
    // no-op in finally: the names are already gone.
    const code = codeOf(blockOf(read(patched[0]), TAG));
    const enableFn = code.slice(code.indexOf('function Enable-PilotScheduledTasksAfterDeploy'));
    expect(enableFn).not.toMatch(/PILOT_HELD_TASK_NAMES = @\(\)/);
    expect(enableFn).toMatch(/stillHeld/);
    expect(enableFn).toMatch(/PILOT_HELD_TASK_NAMES = @\(\$stillHeld\)/);
  });

  it('Cmd-Install disables, then stops, then deploys', () => {
    for (const file of PINNED) {
      const body = functionBody(read(file), 'Cmd-Install');
      const tryAt = body.indexOf('try {');
      const stopAt = body.indexOf('Stop-PilotService');
      const disableAt = body.indexOf('Disable-PilotScheduledTasksDuringDeploy');
      const deployAt = body.indexOf('Deploy-Package');
      const finallyAt = body.indexOf('} finally {');
      expect(stopAt, `${file}: Stop-PilotService missing from Cmd-Install`).toBeGreaterThan(-1);
      expect(disableAt, `${file}: Disable missing from Cmd-Install`).toBeGreaterThan(-1);
      expect(deployAt, `${file}: Deploy-Package missing from Cmd-Install`).toBeGreaterThan(-1);
      expect(disableAt, `${file}: Disable must precede Stop`).toBeLessThan(stopAt);
      expect(stopAt).toBeLessThan(deployAt);
      // Ctrl+C during Disable must still hit Enable in finally.
      expect(tryAt, `${file}: Cmd-Install try missing`).toBeGreaterThan(-1);
      expect(finallyAt, `${file}: Cmd-Install finally missing`).toBeGreaterThan(-1);
      expect(tryAt, `${file}: Disable must be inside try`).toBeLessThan(disableAt);
      expect(disableAt, `${file}: Disable must be before finally`).toBeLessThan(finallyAt);
    }
  });

  it('Cmd-Upgrade disables, then stops, then deploys', () => {
    for (const file of PINNED) {
      const body = functionBody(read(file), 'Cmd-Upgrade');
      const stopAt = body.indexOf('Stop-PilotService');
      const disableAt = body.indexOf('Disable-PilotScheduledTasksDuringDeploy');
      const deployAt = body.indexOf('Deploy-Package');
      expect(stopAt, `${file}: Stop-PilotService missing from Cmd-Upgrade`).toBeGreaterThan(-1);
      expect(disableAt, `${file}: Disable missing from Cmd-Upgrade`).toBeGreaterThan(-1);
      expect(deployAt, `${file}: Deploy-Package missing from Cmd-Upgrade`).toBeGreaterThan(-1);
      expect(disableAt, `${file}: Disable must precede Stop`).toBeLessThan(stopAt);
      expect(stopAt).toBeLessThan(deployAt);
    }
  });

  it('enables before start, and again in finally', () => {
    // Enable must precede Start-ScheduledTask: a disabled task will not start.
    // finally must also Enable so Ctrl+C / exit 1 cannot leave the tasks disabled.
    // Start itself stays on the success path -- a failed postinstall must not launch
    // a collector whose hooks were never written.
    for (const file of PINNED) {
      for (const fn of ['Cmd-Install', 'Cmd-Upgrade']) {
        const body = functionBody(read(file), fn);
        const enables = [];
        let from = 0;
        while (true) {
          const at = body.indexOf('Enable-PilotScheduledTasksAfterDeploy', from);
          if (at === -1) break;
          enables.push(at);
          from = at + 1;
        }
        expect(enables.length, `${file} ${fn}: expected Enable twice (before start + finally)`).toBeGreaterThanOrEqual(2);
        expect(body).toMatch(/finally[\s\S]*Enable-PilotScheduledTasksAfterDeploy/);
        const startAt = body.search(/启动服务|启动新版本/);
        expect(startAt, `${file} ${fn}: start prompt missing`).toBeGreaterThan(-1);
        expect(enables[0]).toBeLessThan(startAt);
      }
    }
  });

  it('does not hold tasks during uninstall', () => {
    // Uninstall deletes the tasks. Re-enabling them in a finally would fight
    // Remove-PilotScheduledTasks.
    for (const file of patched) {
      const body = functionBody(read(file), 'Cmd-Uninstall');
      expect(body, file).not.toMatch(/Disable-PilotScheduledTasksDuringDeploy/);
      expect(body, file).not.toMatch(/Enable-PilotScheduledTasksAfterDeploy/);
    }
  });
});

/**
 * A version directory is never rewritten in place, on any install channel.
 *
 * Symptom this pins: re-running the installer over a live install deleted
 * versions/<ver>_<commit>/ and re-populated it while `current` still pointed there.
 * A collector launched in that window (the installer's own "start", or the updater
 * task relaunching it) resolved versions/<current>/dist/index.js against a directory
 * whose node_modules were not back yet and died with
 *   ERR_MODULE_NOT_FOUND: Cannot find package 'pino' imported from ...\dist\index.js
 * recorded in logs/last-startup-crash.json as phase=module_load. The install then
 * reported "Collector task produced no runtime heartbeat" even though the box
 * converged minutes later, once the deploy had finished.
 *
 * Rule: deploy into a directory nothing points at (a fresh suffixed sibling when the
 * name is taken), install dependencies there, and only then write current/previous.
 * Version and commit are read from the VERSION file, not from the directory name, so
 * the suffix is inert for Get-VersionFromDir / Get-CommitFromDir / GC-OldVersions.
 */
import { describe, it, expect } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '../../..');

// installer-opensource.ps1 is the only one of these that exists in the open-source repo;
// the other two arrive with the internal mirror, and the same assertions then cover them.
const INSTALLERS = [
  'deploy/installer.ps1',
  'deploy/installer-inner.ps1',
  'deploy/installer-opensource.ps1',
].filter(rel => existsSync(join(repoRoot, rel)));

/** Body of `function <name> { ... }` up to the next top-level `function` or EOF. */
function functionBody(text, name) {
  const start = text.indexOf(`function ${name} {`);
  expect(start, `${name} not found`).toBeGreaterThan(-1);
  const rest = text.slice(start);
  const next = rest.search(/\n# =+\nfunction |\nfunction /);
  return next === -1 ? rest : rest.slice(0, next);
}

describe('Deploy-Package never overwrites a version directory in place', () => {
  it('finds the installers to check', () => {
    // Guards against a silently empty sweep (renamed file, wrong cwd).
    expect(INSTALLERS.length).toBeGreaterThanOrEqual(1);
  });

  for (const rel of INSTALLERS) {
    describe(rel, () => {
      const text = readFileSync(join(repoRoot, rel), 'utf8');
      const body = functionBody(text, 'Deploy-Package');

      it('picks a fresh directory name instead of removing the existing one', () => {
        // The versioned branch must not rm -rf its own target. The legacy
        // (no-VERSION-file) branch still overwrites $PERMANENT_DIR, which nothing
        // points at through `current`, so it is matched narrowly by variable name.
        expect(body).not.toMatch(/Remove-Item\s+\$target\s+-Recurse/);
        expect(body).toMatch(/if \(Test-Path -LiteralPath \$target\)/);
        expect(body).toMatch(/\$deployedDirName = "\$\{baseDirName\}_\$\{suffix\}"/);
      });

      it('publishes current only after dependencies are installed', () => {
        const setCurrent = body.indexOf('Set-Content -Path $currentFile -Value $deployedDirName');
        const installDeps = body.indexOf('Ensure-NodeModules');
        expect(setCurrent, 'current is not published from $deployedDirName').toBeGreaterThan(-1);
        expect(installDeps).toBeGreaterThan(-1);
        expect(setCurrent).toBeGreaterThan(installDeps);
      });

      it('records the outgoing version as previous, without clobbering itself', () => {
        expect(body).toMatch(/if \(\$oldDir -and \$oldDir -ne \$deployedDirName\) \{/);
      });
    });
  }
});

import { afterEach, describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { spawnSync } from 'node:child_process';

const shell = fs.readFileSync(new URL('../../../deploy/installer-opensource.sh', import.meta.url).pathname, 'utf8');
const powershell = fs.readFileSync(new URL('../../../deploy/installer-opensource.ps1', import.meta.url).pathname, 'utf8');
const dirs = [];
afterEach(() => { for (const dir of dirs.splice(0)) fs.rmSync(dir, { recursive: true, force: true }); });
function fixture() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'installer-workspace-')); dirs.push(dir);
  const file = path.join(dir, 'config.json');
  fs.writeFileSync(file, JSON.stringify({ privacy: { excludeWorkspaces: ['/old'], custom: true }, userId: 'existing' }));
  return { dir, file };
}
function bashWrite(paths = []) {
  const { dir, file } = fixture();
  const fn = shell.slice(shell.indexOf('write_config() {'), shell.indexOf('install_loongsuite_pilot_command() {'));
  const start = fn.indexOf("const fs = require('fs');");
  const endText = "fs.writeFileSync(path, JSON.stringify(config, null, 2) + '\\n');";
  const end = fn.indexOf(endText) + endText.length;
  const code = fn.slice(start, end)
    .replaceAll("'$config_file'", JSON.stringify(file))
    .replaceAll("'$DATA_DIR'", JSON.stringify(dir))
    .replace(/\$\{[A-Z_]+\}/g, '');
  const script = path.join(dir, 'writer.cjs');
  fs.writeFileSync(script, code);
  const result = spawnSync(process.execPath, [script], { encoding: 'utf8', input: '[]', env: {
    ...process.env, LP_EXCLUDE_WORKSPACES: paths.length ? JSON.stringify(paths) : '',
  } });
  expect(result.status, result.stderr).toBe(0);
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

