// A re-install can leave the previous version's collector running, and nothing about it
// looks wrong.
//
// `start` is a deliberate no-op when a collector is already running, and on a re-install
// one usually is: Stop-PilotService only ends the current task instance, and Task
// Scheduler (or the updater's collector watchdog) relaunches it within seconds -- while
// `current` still names the OLD version dir, because Deploy-Package writes the new one
// only after Ensure-NodeModules. collector-daemon.js resolves `current` exactly once at
// startup, so that survivor serves the old dist forever while `status` reads `current`
// and reports the NEW version. The install prints "Service started"; the bytes the user
// just installed are never loaded.
//
// It went quiet the moment re-installs stopped overwriting the live version dir (pinned by
// installer-version-dir-not-overwritten.test.mjs): while Deploy-Package still did Remove-Item on it,
// the survivor died with ERR_MODULE_NOT_FOUND and got restarted onto the new version, so
// the bug announced itself. Keeping the old dir is right -- Restart-StaleCollector is the
// other half of it.
//
// Only the .ps1 installers are pinned here: the survivor is a Task Scheduler / watchdog
// artefact, and the .sh installers have no equivalent relaunch racing the deploy.
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';

const PS1_INSTALLERS = [
  'deploy/installer.ps1',
  'deploy/installer-inner.ps1',
  'deploy/installer-opensource.ps1',
];

// The script the installers deploy as loongsuite-pilot-service.ps1, and whose `start`
// output the gate below matches against.
const SERVICE_SCRIPT = 'scripts/loongsuite-pilot.ps1';

const read = (f) => readFileSync(f, 'utf-8');

const blockOf = (text, tag) => {
  const re = new RegExp(`^\\s*# >>> ${tag} >>>\\n[\\s\\S]*?^\\s*# <<< ${tag} <<<\\n`, 'm');
  const m = text.match(re);
  return m ? m[0] : null;
};

const codeOf = (text) => text
  .split('\n')
  .filter(line => !/^\s*#/.test(line))
  .join('\n');

const present = PS1_INSTALLERS.filter(existsSync);

describe('installers displace a stale collector after re-installing', () => {
  it('defines Restart-StaleCollector', () => {
    expect(present.length).toBeGreaterThanOrEqual(1);
    for (const file of present) {
      const block = blockOf(read(file), 'pilot-restart-stale-collector');
      expect(block, `${file}: pilot-restart-stale-collector block missing`).toBeTruthy();
      expect(codeOf(block), file).toMatch(/function Restart-StaleCollector/);
    }
  });

  it('the block is byte-identical across the .ps1 installers', () => {
    // The three installers are near-copies maintained by hand; a block that drifts in one
    // of them is a variant that quietly goes back to serving the old dist.
    const blocks = present.map(f => blockOf(read(f), 'pilot-restart-stale-collector'));
    expect(blocks.filter(b => !b)).toEqual([]);
    expect(new Set(blocks).size).toBe(1);
  });

  it('uses restart-collector, not a bare restart', () => {
    // `restart` would also bounce the updater. restart-collector is what the updater
    // itself uses after deploying a version: stop unconditionally, kill orphans,
    // re-register, start -- and leave the updater running.
    const code = codeOf(blockOf(read(present[0]), 'pilot-restart-stale-collector'));
    expect(code).toMatch(/restart-collector/);
    expect(code.match(/\brestart\b(?!-collector)/), 'bare restart').toBeNull();
  });

  it('does nothing on a fresh install', () => {
    // No prior version means no survivor to displace, and `start` already launched the
    // collector from the new `current`. Bouncing it again would only slow the install.
    // $true, not a bare return: nothing to do is not a failure to displace.
    const code = codeOf(blockOf(read(present[0]), 'pilot-restart-stale-collector'));
    expect(code).toMatch(/if \(-not \$priorVersion\) \{ return \$true \}/);
  });

  it('reports a failed displacement instead of swallowing it', () => {
    // Native commands do not throw on a nonzero exit, so $LASTEXITCODE is the only signal
    // there is. Cmd-RestartCollector exits 1 when it cannot resolve node, when the
    // bootstrap entry is gone, and when the service manager refuses -- in all three the
    // survivor keeps serving the OLD version dir, and `2>$null | Out-Null` made that
    // indistinguishable from success.
    const code = codeOf(blockOf(read(present[0]), 'pilot-restart-stale-collector'));
    expect(code).toMatch(/if \(\$LASTEXITCODE -eq 0\) \{ return \$true \}/);
    expect(code).toMatch(/\$script:PILOT_LAST_RESTART_ERR = "restart-collector \(exit \$LASTEXITCODE\)/);
    expect(code).toMatch(/return \$false/);
    // Nothing may be discarded: no `| Out-Null` on the restart itself.
    expect(code).not.toMatch(/restart-collector[^\n]*Out-Null/);
  });

  it('only bounces the collector when start found one already running', () => {
    // Displacing on every deploy costs more than it buys. Task Scheduler grants a task's own
    // principal Read, Synchronize -- every write ACE sits on BUILTIN\Administrators, which
    // UAC filters out of a -RunLevel Limited token -- so re-registering a task that already
    // exists is denied outright on the machines this runs on. Callers treat a failed
    // displacement as a failed deploy, so bouncing a collector `start` had just launched
    // correctly turns a good upgrade into a rollback.
    //
    // `already running` is the one line that says a survivor was there: Cmd-Start prints it
    // off Get-CollectorRuntime or the pid file and returns without starting anything. Any
    // other output means `start` did the launching, from the new `current`.
    const code = codeOf(blockOf(read(present[0]), 'pilot-restart-stale-collector'));
    expect(code).toMatch(/if \(\(\$startOutput \| Out-String\) -notmatch "already running"\) \{ return \$true \}/);
  });

  it('the line that gate reads is still the line start prints', () => {
    // The gate above is a string match against another script's output, so that string is
    // load-bearing in both directions: reword Cmd-Start and every installer silently stops
    // displacing anything, which is the original bug with no symptom.
    expect(read(SERVICE_SCRIPT)).toMatch(/Write-Host "loongsuite-pilot is already running \(PID /);
  });

  it('every installer calls it with the prior version and the start output, after start', () => {
    for (const file of present) {
      const text = read(file);
      const lines = text.split('\n');
      const calls = lines
        .map((line, i) => [i + 1, line])
        .filter(([, line]) => /Restart-StaleCollector \$/.test(line));
      expect(calls.length, `${file}: never called`).toBeGreaterThanOrEqual(1);

      for (const [lineNo, line] of calls) {
        // Three arguments, all variables: the resolved service entry, the version that was
        // current before this deploy, and what `start` printed. A literal or a missing
        // argument means one of the guards turns the whole thing into a no-op. And the
        // verdict has to be captured -- see below for what has to happen to it.
        const args = line.trim().match(/^\$\w+ = Restart-StaleCollector \$(\w+) \$(\w+) \$(\w+)$/);
        expect(args, `${file}:${lineNo}: expected three variable arguments`).toBeTruthy();

        // It has to run after the start attempt -- displacing a survivor before `start`
        // just lets the watchdog put the old one back.
        const before = lines.slice(0, lineNo - 1).join('\n');
        expect(/-File \$\S+ start\b|& \$\S+ start\b/.test(before), `${file}:${lineNo}: no preceding start`).toBe(true);

        // And the third argument has to be that attempt's own output. An unset variable
        // never matches "already running", so a call site that forgets to capture disables
        // the displacement everywhere without failing anything.
        const startVar = args[3];
        expect(
          new RegExp(`\\$${startVar} = & [^\\n]*\\bstart\\b`).test(before),
          `${file}:${lineNo}: $${startVar} is not filled from start`,
        ).toBe(true);
        // Capturing it must not hide it: the start diagnostics still go to the user.
        expect(
          new RegExp(`\\$${startVar} \\| ForEach-Object \\{ Write-Host \\$_ \\}`).test(text),
          `${file}:${lineNo}: $${startVar} is captured and never shown`,
        ).toBe(true);
      }
    }
  });

  it('no installer reports success when the displacement failed', () => {
    // `status` resolves `current`, and the survivor answers to it exactly as well as the new
    // collector would, so "is running" cannot tell them apart. An installer that captures
    // the verdict and then prints its check mark anyway is back to the original bug with
    // extra steps, so the captured variable has to reach the decision that prints it.
    for (const file of present) {
      const lines = read(file).split('\n');
      const calls = lines
        .map((line, i) => [i + 1, line])
        .filter(([, line]) => /Restart-StaleCollector \$/.test(line));

      for (const [lineNo, line] of calls) {
        const captured = line.trim().match(/^\$(\w+) = Restart-StaleCollector /);
        expect(captured, `${file}:${lineNo}: verdict discarded`).toBeTruthy();
        const after = lines.slice(lineNo).join('\n');
        const used = new RegExp(`(-and \\$${captured[1]}\\b|-not \\$${captured[1]}\\b|return \\$${captured[1]}\\b)`);
        expect(used.test(after), `${file}:${lineNo}: $${captured[1]} never gates anything`).toBe(true);
      }
    }
  });
});

// Uninstall must not be abortable by something that has nothing to do with uninstalling.
//
// A measured Windows box left `%USERPROFILE%\.loongsuite-pilot\config.json` -- SLS
// AccessKeySecret and CMS license key inside it -- on disk after `-Uninstall -Purge`
// reported nothing wrong to look at. The chain:
//
//   1. Resolve-Node probes third-party version managers, and NVM_HOME is commonly a
//      *machine*-level variable pointing into another account's profile. A bare
//      Test-Path on an unreadable directory emits a PermissionDenied
//      UnauthorizedAccessException record, which $ErrorActionPreference = "Stop" -- set
//      in the header of every one of these scripts -- promotes to terminating.
//   2. Cmd-Uninstall called Resolve-Node bare, before any cleanup step. One terminating
//      error there skipped the plugin cleanups, the install-directory removal, and the
//      `if ($Purge)` branch that deletes the data dir. Nothing downstream repairs that:
//      the next `-Purge` takes the same path and dies at the same line.
//   3. The one failure mode that *is* expected -- scheduled tasks owned by
//      BUILTIN\Administrators after an elevated install -- was reported as a bare
//      "ERROR: Access is denied." line, because the diagnostic `throw` behind it was
//      unreachable (see the EAP assertions below), and its text taught the workaround as
//      if elevation were a requirement of uninstall rather than a consequence of how the
//      install ran.
//
// So this file pins three separable things: the probes stay non-fatal, uninstall keeps
// going when Node cannot be resolved at all, and the native-command diagnostic actually
// reaches the user. It sweeps whatever .ps1 the repo tracks rather than a fixed list, so
// the same file is meaningful in the open-source mirror (one installer) and downstream
// (three plus the service wrapper) without editing. The prose form of the native-stderr
// rule is pinned separately, by whichever repo's AGENTS.md carries that section.
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';

const PS1 = [
  'deploy/installer.ps1',
  'deploy/installer-inner.ps1',
  'deploy/installer-opensource.ps1',
  'scripts/loongsuite-pilot.ps1',
].filter(existsSync);

const read = (f) => readFileSync(f, 'utf-8');

// Top-level functions in these scripts close with `}` in column 0.
const funcOf = (text, name) => {
  const start = text.indexOf(`function ${name} {`);
  if (start < 0) return null;
  const end = text.indexOf('\n}\n', start);
  return end < 0 ? text.slice(start) : text.slice(start, end + 3);
};

const codeOf = (text) => text
  .split('\n')
  .filter(line => !/^\s*#/.test(line))
  .join('\n');

const blockOf = (text, tag) => {
  const re = new RegExp(`^\\s*# >>> ${tag} >>>\\n[\\s\\S]*?^\\s*# <<< ${tag} <<<\\n`, 'm');
  const m = text.match(re);
  return m ? m[0] : null;
};

describe('Resolve-Node cannot take the caller down with it', () => {
  it('finds the scripts to check', () => {
    // Guards against a silently empty sweep (wrong cwd, renamed files).
    expect(PS1.length).toBeGreaterThanOrEqual(2);
    expect(PS1).toContain('scripts/loongsuite-pilot.ps1');
  });

  for (const file of PS1) {
    it(`${file}: the version-manager probes in Resolve-Node are non-fatal`, () => {
      // Scoped to the third-party roots on purpose. These are the only paths here that
      // belong to somebody else: NVM_HOME is routinely a machine-level variable pointing
      // into another account's profile, and reading such a directory is a
      // PermissionDenied record, not a "not found". The pin file and its parent live
      // under the caller's own data dir, where failing fast is still the right answer.
      const body = funcOf(read(file), 'Resolve-Node');
      expect(body, `${file}: Resolve-Node not found`).toBeTruthy();
      const probes = codeOf(body)
        .split('\n')
        .filter(l => l.includes('Test-Path'))
        .filter(l => /NVM_HOME|\$nvmHome|\$fnmDir/.test(l))
        .map(l => l.trim());
      // Both roots are still probed -- a rename must not empty this check.
      expect(probes.length, `${file}: version-manager probes not found`).toBe(2);
      const unguarded = probes.filter(l => !l.includes('-ErrorAction SilentlyContinue'));
      expect(unguarded, `${file}: version-manager probe at "Stop"`).toEqual([]);
    });
  }
});

const INSTALLERS = PS1.filter(f => f.startsWith('deploy/installer'));

describe('uninstall continues when Node cannot be resolved', () => {
  for (const file of INSTALLERS) {
    it(`${file}: Cmd-Uninstall guards its Resolve-Node call`, () => {
      const body = funcOf(read(file), 'Cmd-Uninstall');
      expect(body, `${file}: Cmd-Uninstall not found`).toBeTruthy();
      const code = codeOf(body);
      // The assignment must sit inside a try. Matching the shape rather than just
      // "contains try" -- Cmd-Uninstall is full of unrelated try blocks.
      expect(code, file).toMatch(/try\s*\{\s*\n\s*\$script:NODE_BIN = Resolve-Node\s*\n\s*\}\s*catch\s*\{/);
      // And the failure has to be visible: silently continuing with no Node would
      // report a clean uninstall that skipped every JSON config on the machine.
      expect(code, file).toMatch(/\$script:NODE_BIN = ""/);
    });

    it(`${file}: every Node-dependent cleanup skips explicitly without a Node`, () => {
      // Consequence of the guard above: uninstall now reaches these with an empty
      // $NODE_BIN. Remove-HookConfigs was the one that did not check, so it would have
      // run `& ""` and then printed its success line for a file it never touched.
      for (const fn of ['Remove-HookConfigs', 'Remove-OpenClawPlugin']) {
        const body = funcOf(read(file), fn);
        if (!body) continue;
        expect(codeOf(body), `${file}: ${fn}`).toMatch(/if \(-not \$script:NODE_BIN\)/);
      }
    });
  }
});

describe('a refusal to unpatch DSH is gated on something actually dangling', () => {
  // Remove-DshYamlPatch is the first thing Cmd-Uninstall calls and it deliberately
  // throws rather than delete plugin assets a DSH patch still references. Reasonable --
  // except the no-Node branch threw unconditionally, and $pluginDir lives under
  // $DataDir, so the throw skipped the `if ($Purge)` branch at the very bottom of
  // Cmd-Uninstall: the same config.json this file exists to get deleted survived, on
  // machines that had never patched DSH at all. Two refusals, one question, so both
  // branches have to ask it.
  for (const file of INSTALLERS) {
    it(`${file}: both refusals check the managed block first`, () => {
      const src = read(file);
      const code = codeOf(funcOf(src, 'Remove-DshYamlPatch'));
      const refusals = code.split('\n').filter(l => l.includes('throw'));
      // Missing helper, no Node, and cleanup.mjs exiting non-zero. The third one has run
      // the unpatch and knows it failed, so it needs no probe.
      expect(refusals.length, `${file}: refusal count changed`).toBe(3);
      const unguarded = refusals.filter(l => !/referenced by|DSH YAML patch at|Pilot assets were preserved/.test(l));
      expect(unguarded, `${file}: a refusal names no reason`).toEqual([]);
      // The probe, not an inline Select-String: an unreadable third-party file must not
      // be able to fail the working path, which is why this moved behind a helper.
      expect(code, file).not.toContain('Select-String');
      const gates = code.split('\n').filter(l => l.includes('Test-DshPatchStillManaged -PatchPath'));
      expect(gates.length, `${file}: both branches must gate`).toBe(2);
      // And the no-Node branch must fall through to a skip, not to the unpatch call.
      expect(code, file).toMatch(/if \(-not \$script:NODE_BIN\)[\s\S]*?Msg[\s\S]*?\n\s*return\n/);
    });

    it(`${file}: the probe answers "managed" when it cannot tell`, () => {
      const block = blockOf(read(file), 'dsh-unpatch-refusal');
      expect(block, `${file}: dsh-unpatch-refusal block missing`).toBeTruthy();
      const code = codeOf(block);
      // A missing patch file is a real "nothing dangles". A patch file we failed to read
      // is not, and answering $false there would delete the assets anyway.
      expect(code, file).toMatch(/Test-Path[^\n]*-ErrorAction SilentlyContinue[^\n]*\{ return \$false \}/);
      expect(code, file).toMatch(/catch\s*\{\s*\n\s*return \$true/);
    });
  }

  it('the block is byte-identical across the installers', () => {
    const blocks = INSTALLERS.map(f => blockOf(read(f), 'dsh-unpatch-refusal'));
    expect(blocks.filter(b => !b)).toEqual([]);
    expect(new Set(blocks).size).toBe(1);
  });

  for (const file of INSTALLERS) {
    it(`${file}: a preserved data dir says what is still in it`, () => {
      // The counterpart to the refusals above: whenever uninstall keeps $DataDir, this is
      // the only line telling the user an AccessKeySecret is still readable there.
      const code = codeOf(funcOf(read(file), 'Cmd-Uninstall'));
      expect(code, file).toContain('config.json holds reporting credentials');
    });
  }
});

describe('the scheduled-task failure reaches the user', () => {
  for (const file of INSTALLERS) {
    it(`${file}: the schtasks call runs at "Continue" and restores in finally`, () => {
      // On Windows PowerShell 5.1 a native command that writes stderr while a 2>
      // redirection is in effect raises a NativeCommandError, and EAP=Stop promotes it
      // to a terminating error whose Message is just the raw stderr line. schtasks.exe
      // prints "ERROR: Access is denied." there on exactly the failure this branch
      // exists to report, so the throw below it never ran.
      const body = funcOf(read(file), 'Remove-OnePilotScheduledTask');
      expect(body, `${file}: Remove-OnePilotScheduledTask not found`).toBeTruthy();
      const code = codeOf(body);
      expect(code, file).toContain('$ErrorActionPreference = "Continue"');
      expect(code, file).toMatch(/\}\s*finally\s*\{\s*\n\s*\$ErrorActionPreference = \$prevEAP/);
      // Exit code from the call, not from whatever ran before it.
      expect(code, file).toContain('$schtasksExit = $LASTEXITCODE');
      // Pre-seeded to non-zero: a schtasks.exe that cannot launch at all must not
      // inherit a stale $LASTEXITCODE of 0 and be read as success.
      expect(code, file).toContain('$schtasksExit = 1');
      expect(code, file).not.toContain('catch {}');
    });

    it(`${file}: the message names the cause, not just the workaround`, () => {
      // It used to say only "Run uninstall from an elevated PowerShell.", which reads as
      // "uninstall needs admin". It does not. The tasks are owned by Administrators
      // because the *install* ran elevated, and the durable fix is to install without
      // elevation -- so both halves have to be in the text.
      const code = codeOf(funcOf(read(file), 'Remove-OnePilotScheduledTask'));
      expect(code, file).toContain('BUILTIN\\Administrators');
      expect(code, file).toContain('does not need administrator');
      expect(code, file).toContain('reinstall without elevation');
      // The stderr that explains which of the two failures happened must be quoted.
      expect(code, file).toContain('$schtasksDetail');
      // And quoted as the stderr line, not as a rendered ErrorRecord. At "Continue" the
      // NativeCommandError still goes to the error stream, so 2>&1 merges the record
      // object; `$schtasksOut | Out-String` therefore expanded one stderr line into a
      // six-line PowerShell error block -- source line, squiggles, CategoryInfo -- inside
      // the sentence. Measured on a 5.1 box, where schtasks.exe produced two records for
      // one line, the second empty.
      expect(code, file).not.toContain('$schtasksOut | Out-String');
      expect(code, file).toContain('$schtasksLine.Exception.Message');
    });
  }
});

describe('an elevated install says what it costs', () => {
  // Cheap half of the fix. Rewriting the task security descriptor after registration so
  // the user can delete their own tasks again is the real repair and is not attempted
  // here; until then the install has to tell the user what it just did to them.
  for (const file of INSTALLERS) {
    it(`${file}: warns before doing any work`, () => {
      const src = read(file);
      const block = blockOf(src, 'pilot-elevation-warning');
      expect(block, `${file}: pilot-elevation-warning block missing`).toBeTruthy();
      const code = codeOf(block);
      expect(code, file).toMatch(/function Test-PilotElevated/);
      // Best-effort by construction: the cast and GetCurrent() are both CLM-forbidden,
      // so on a WDAC box this throws and the catch has to swallow it. Losing a hint is
      // acceptable; failing an install over a hint is not.
      expect(code, file).toMatch(/catch\s*\{\s*\n\s*return \$false/);
      // Called from Cmd-Install before Check-Deps / Download-AndExtract, so Ctrl+C is
      // still free at that point.
      const install = codeOf(funcOf(src, 'Cmd-Install'));
      expect(install, file).toContain('Warn-ElevatedInstall');
      expect(
        install.indexOf('Warn-ElevatedInstall'),
        `${file}: warning must precede Check-Deps`,
      ).toBeLessThan(install.indexOf('Check-Deps'));
    });
  }

  it('the block is byte-identical across the installers', () => {
    // Three hand-maintained near-copies; a block that drifts in one of them is a
    // variant nobody is testing.
    const blocks = INSTALLERS.map(f => blockOf(read(f), 'pilot-elevation-warning'));
    expect(blocks.filter(b => !b)).toEqual([]);
    expect(new Set(blocks).size).toBe(1);
  });
});

// Overlay `install` used to SIGTERM only the collector pid file. The updater
// stayed up, and gcOldVersions() deletes any versions/<dir> that is not
// current/previous -- including the directory this deploy just copied, before
// current is published. installer-opensource.sh writes current after
// node_modules + postinstall, so that window is minutes (same class of bug as
// Windows Stop-ScheduledTask without Disable).
//
// Unix stop already unloads LaunchAgent / disables systemd (autostart_remove).
// Overlay install has to call that, the same way `cmd_upgrade` always did; a
// collector-only pid kill does not close the GC race.
import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';

const INTERNAL_SH = [
  'deploy/installer.sh',
  'deploy/installer-inner.sh',
];
const OPENSOURCE_SH = 'deploy/installer-opensource.sh';
const SH_INSTALLERS = [...INTERNAL_SH, OPENSOURCE_SH];

const read = (f) => readFileSync(f, 'utf-8');

const blockOf = (text, tag) => {
  const re = new RegExp(`^\\s*# >>> ${tag} >>>\\n[\\s\\S]*?^\\s*# <<< ${tag} <<<\\n`, 'm');
  const m = text.match(re);
  return m ? m[0] : null;
};

const codeOf = (text) => text
  .split('\n')
  .filter(line => !/^\s*#/.test(line))
  .join('\n');

const fnOf = (text, name) => {
  const start = text.indexOf(`${name}() {`);
  if (start < 0) return '';
  const end = text.indexOf('\n# ============================================================', start + 1);
  return end > start ? text.slice(start, end) : text.slice(start);
};

const present = SH_INSTALLERS.filter(existsSync);
const patched = present.filter(f => blockOf(read(f), 'pilot-stop-for-deploy'));

describe('sh overlay install stops updater, not just the collector pid', () => {
  it('defines stop_pilot_for_deploy', () => {
    expect(patched.length).toBeGreaterThanOrEqual(1);
    for (const file of INTERNAL_SH.filter(existsSync)) {
      expect(blockOf(read(file), 'pilot-stop-for-deploy'), `${file}: pilot-stop-for-deploy block missing`).toBeTruthy();
    }
    for (const file of patched) {
      expect(codeOf(blockOf(read(file), 'pilot-stop-for-deploy')), file).toMatch(/stop_pilot_for_deploy\(\) \{/);
    }
  });

  it('the block is byte-identical across the patched .sh installers', () => {
    const blocks = patched.map(f => blockOf(read(f), 'pilot-stop-for-deploy'));
    expect(blocks.filter(b => !b)).toEqual([]);
    expect(new Set(blocks).size).toBe(1);
  });

  it('calls loongsuite-pilot stop, not a collector-only kill', () => {
    const code = codeOf(blockOf(read(patched[0]), 'pilot-stop-for-deploy'));
    expect(code).toMatch(/run_pilot_cli stop/);
    expect(code).toMatch(/loongsuite-pilot-updater\.pid/);
    // The CLI is how autostart_remove happens. Pid fallback is for a missing CLI,
    // not the overlay path.
    expect(code).toMatch(/command -v loongsuite-pilot/);
    // Unix hold IS this stop. Swallowing it hides a still-live updater/GC window.
    expect(code).not.toMatch(/run_pilot_cli stop\s+2>\/dev\/null/);
    expect(code).toMatch(/Could not stop the service/);
  });

  it('passes the installer data dir into every CLI verb after stop', () => {
    // Without this, --data-dir overlay would stop the custom instance and then
    // start/status/rollback the default ~/.loongsuite-pilot one.
    const code = codeOf(blockOf(read(patched[0]), 'pilot-stop-for-deploy'));
    expect(code).toMatch(/run_pilot_cli\(\)/);
    expect(code).toMatch(/LOONGSUITE_PILOT_DATA_DIR="\$DATA_DIR"/);
    // deploy_package writes versions/current under $HOME/.loongsuite-pilot.
    // Pointing the CLI cache at DATA_DIR would start/rollback a different tree.
    expect(code).not.toMatch(/LOONGSUITE_PILOT_CACHE_DIR=/);
  });

  it('sets PILOT_HELD_FOR_DEPLOY before stop, so a killed stop still restores', () => {
    const code = codeOf(blockOf(read(patched[0]), 'pilot-stop-for-deploy'));
    const stopFn = code.slice(
      code.indexOf('stop_pilot_for_deploy() {'),
      code.indexOf('restore_pilot_after_deploy() {'),
    );
    const heldAt = stopFn.lastIndexOf('PILOT_HELD_FOR_DEPLOY=1');
    const cliStopAt = stopFn.indexOf('run_pilot_cli stop');
    expect(heldAt).toBeGreaterThan(-1);
    expect(cliStopAt).toBeGreaterThan(-1);
    expect(heldAt).toBeLessThan(cliStopAt);
  });

  it('restores autostart after a failed overlay, except in container mode', () => {
    // stop deletes LaunchAgent/systemd unit files. Unix restore is `start`,
    // which re-registers autostart. That is safe because deploy_package
    // publishes `current` only after node_modules + postinstall: abort still
    // points at the previous complete version (or nothing, on a fresh install).
    // A docker build layer must not launch a daemon.
    const code = codeOf(blockOf(read(patched[0]), 'pilot-stop-for-deploy'));
    expect(code).toMatch(/restore_pilot_after_deploy\(\)/);
    expect(code).toMatch(/INSTALL_MODE:-host/);
    expect(code).toMatch(/run_pilot_cli start/);
    // Swallowing start hides the only signal that autostart did not come back.
    expect(code).not.toMatch(/run_pilot_cli start\s+>\/dev\/null/);
    expect(code).toMatch(/Could not restore autostart/);
  });

  it('deploy_package publishes current only after postinstall', () => {
    // Overlay restore is `start`. If current already named the new dir, abort
    // would launch a collector with no hooks / no node_modules.
    for (const file of SH_INSTALLERS.filter(existsSync)) {
      const fn = fnOf(read(file), 'deploy_package');
      const writeAt = fn.indexOf('echo "$dir_name" > "$current_file.tmp"');
      const postAt = fn.indexOf('scripts/postinstall.js');
      const npmFailAt = fn.indexOf('Dependency installation failed');
      expect(writeAt, `${file}: current pointer write missing`).toBeGreaterThan(-1);
      expect(postAt, `${file}: postinstall missing`).toBeGreaterThan(-1);
      expect(npmFailAt, `${file}: npm failure path missing`).toBeGreaterThan(-1);
      expect(writeAt, `${file}: current published before postinstall`).toBeGreaterThan(postAt);
      expect(writeAt, `${file}: current published before npm install`).toBeGreaterThan(npmFailAt);
      expect(fn.slice(npmFailAt, writeAt), `${file}: npm failure does not return before current write`)
        .toMatch(/return 1/);
      expect(fn.slice(postAt, writeAt), `${file}: postinstall failure does not return before current write`)
        .toMatch(/return 1/);
    }
  });

  it('cmd_install and cmd_upgrade both call it before deploy_package', () => {
    for (const file of patched) {
      const text = read(file);
      expect(text.match(/stop_pilot_for_deploy/g)?.length, `${file}: expected helper + two call sites`)
        .toBeGreaterThanOrEqual(3);

      const install = fnOf(text, 'cmd_install');
      const upgrade = fnOf(text, 'cmd_upgrade');
      expect(install, `${file}: cmd_install missing`).toContain('stop_pilot_for_deploy');
      expect(upgrade, `${file}: cmd_upgrade missing`).toContain('stop_pilot_for_deploy');

      const stopAt = install.indexOf('stop_pilot_for_deploy');
      const deployAt = install.indexOf('deploy_package');
      expect(stopAt, `${file}: cmd_install never calls stop_pilot_for_deploy`).toBeGreaterThan(-1);
      expect(deployAt, `${file}: cmd_install never calls deploy_package`).toBeGreaterThan(-1);
      expect(stopAt, `${file}: cmd_install stops after deploy_package`).toBeLessThan(deployAt);

      const upStopAt = upgrade.indexOf('stop_pilot_for_deploy');
      const upDeployAt = upgrade.indexOf('deploy_package');
      expect(upStopAt, file).toBeGreaterThan(-1);
      expect(upDeployAt, file).toBeGreaterThan(-1);
      expect(upStopAt, `${file}: cmd_upgrade stops after deploy_package`).toBeLessThan(upDeployAt);

      // The old overlay path printed this and killed only the collector pid.
      expect(install, `${file}: cmd_install still uses the collector-only pid kill`)
        .not.toMatch(/Stopping running service \(PID/);

      expect(install, `${file}: cmd_install EXIT trap does not restore autostart`)
        .toMatch(/restore_pilot_after_deploy/);
      expect(upgrade, `${file}: cmd_upgrade EXIT trap does not restore autostart`)
        .toMatch(/restore_pilot_after_deploy/);

      // start/status/rollback after stop must go through run_pilot_cli so --data-dir matches.
      expect(install, `${file}: cmd_install start is not DATA_DIR-aware`)
        .toMatch(/run_pilot_cli start/);
      expect(upgrade, `${file}: cmd_upgrade start is not DATA_DIR-aware`)
        .toMatch(/run_pilot_cli start/);
      expect(upgrade, `${file}: cmd_upgrade rollback is not DATA_DIR-aware`)
        .toMatch(/run_pilot_cli rollback/);

      const trapAt = (fn) => fn.indexOf("trap 'restore_pilot_after_deploy");
      const stopCall = (fn) => fn.search(/^\s*stop_pilot_for_deploy$/m);
      expect(trapAt(install), `${file}: cmd_install restore trap missing`).toBeGreaterThan(-1);
      expect(stopCall(install), `${file}: cmd_install stop call missing`).toBeGreaterThan(-1);
      expect(trapAt(install), `${file}: cmd_install trap must be armed before stop`)
        .toBeLessThan(stopCall(install));
      expect(trapAt(upgrade), `${file}: cmd_upgrade restore trap missing`).toBeGreaterThan(-1);
      expect(stopCall(upgrade), `${file}: cmd_upgrade stop call missing`).toBeGreaterThan(-1);
      expect(trapAt(upgrade), `${file}: cmd_upgrade trap must be armed before stop`)
        .toBeLessThan(stopCall(upgrade));

      const failAt = upgrade.indexOf('New version failed to start');
      expect(failAt, `${file}: cmd_upgrade start-failure path missing`).toBeGreaterThan(-1);
      expect(upgrade.slice(failAt), `${file}: start-failure path never starts after rollback`)
        .toMatch(/run_pilot_cli start/);
    }
  });

  it('AGENTS.md still names the helper when this repo documents the rule', () => {
    const agents = read('AGENTS.md');
    if (!agents.includes('pilot-stop-for-deploy')) return;
    expect(agents).toContain('tests/unit/deploy/installer-stop-for-deploy.test.mjs');
  });
});
